SELECT team, COUNT(*) AS losses FROM (
    SELECT team1 AS team, match_id FROM Matches WHERE stage = 'Semi Final' AND match_winner = team2 AND season > '2002/03'
    UNION ALL
    SELECT team2 AS team, match_id FROM Matches WHERE stage = 'Semi Final' AND match_winner = team1 AND season > '2002/03'
) GROUP BY team ORDER BY losses DESC;

